CREATE FUNCTION buscar_libros(consulta text)
RETURNS TABLE (id integer, titulo text, rango numeric, fragmento text)
LANGUAGE sql STABLE
AS $$
  SELECT l.id, l.titulo,
         round(ts_rank(l.busqueda, q)::numeric, 4),
         ts_headline('es_sin_tildes', l.resumen, q, 'StartSel=[, StopSel=]')
  FROM libros AS l, websearch_to_tsquery('es_sin_tildes', consulta) AS q
  WHERE l.busqueda @@ q
  ORDER BY 3 DESC, l.id
  LIMIT 10;
$$;
